using System.Net;
using System.Net.Http;
using System.Text;
using Planner.Core;
using Planner.Data;
static class ModelAuthTests
{
    static void Equal<T>(T expected,T actual){if(!Equals(expected,actual))throw new Exception($"expected {expected}, got {actual}");}
    static string Failure(Action action){try{action();}catch(InvalidOperationException ex){return ex.Message;}throw new Exception("expected failure");}
    public static void Register(Action<string,Action> test)
    {
        test("v1.12 Bailian URLs and qwen request auth stay compatible",()=>
        {
            foreach(var (region,host,url) in new[]{("北京","","https://dashscope.aliyuncs.com/compatible-mode/v1/chat/completions"),("新加坡","","https://dashscope-intl.aliyuncs.com/compatible-mode/v1/chat/completions"),("北京"," https://llm-example.cn-beijing.maas.aliyuncs.com/compatible-mode/v1/ ","https://llm-example.cn-beijing.maas.aliyuncs.com/compatible-mode/v1/chat/completions")})
            {
                var uri=LlmClient.Endpoint(RepositoryAgentClient.BailianEndpoint(region,host));Equal(url,uri.AbsoluteUri);
                using var request=ModelHttp.Request(uri,"  \r\nsk-fixture\t ","{\"model\":\"qwen-plus\",\"enable_thinking\":false}");Equal("Bearer",request.Headers.Authorization!.Scheme);Equal("sk-fixture",request.Headers.Authorization.Parameter);Equal("application/json",request.Content!.Headers.ContentType!.MediaType);
            }
        });
        test("credential whitespace and accidental bearer prefix fail before sending",()=>{Equal("",ModelHttp.NormalizeKey(" \r\n"));foreach(var value in new[]{"sk-one two","Bearer sk-fixture","sk-one\ntwo"}){try{ModelHttp.NormalizeKey(value);throw new Exception("expected format rejection");}catch(ArgumentException){}}using var local=ModelHttp.Request(new("http://localhost/v1/chat/completions"),"","{}");Equal(true,local.Headers.Authorization is null);});
        test("401 reports safe provider error code and actual host only",()=>{using var response=new HttpResponseMessage(HttpStatusCode.Unauthorized){Content=new StringContent("{\"error\":{\"code\":\"invalid_api_key\",\"message\":\"secret sk-private and private prompt\"}}")};string message=Failure(()=>ModelHttp.EnsureSuccessAsync(response,new("https://dashscope.aliyuncs.com/compatible-mode/v1/chat/completions"),"对话服务",default).GetAwaiter().GetResult());Equal(true,message.Contains("401")&&message.Contains("invalid_api_key")&&message.Contains("dashscope.aliyuncs.com"));Equal(false,message.Contains("sk-private")||message.Contains("private prompt"));});
        test("reflected key and HTML errors cannot leak through diagnostic code",()=>{foreach(var body in new[]{"<html>sk-private</html>","{\"error\":{\"code\":\"sk-private\"}}","{\"error\":{\"code\":\"opaque-secret\"}}",new string('x',70000)}){using var response=new HttpResponseMessage(HttpStatusCode.Unauthorized){Content=new StringContent(body)};string message=Failure(()=>ModelHttp.EnsureSuccessAsync(response,new("https://dashscope.aliyuncs.com/v1"),"服务",default,"opaque-secret").GetAwaiter().GetResult());Equal(false,message.Contains("sk-private")||message.Contains("opaque-secret")||message.Contains("<html>"));Equal(true,message.Length<600);}});
        test("guided conversation retains service code on authorization rejection",()=>{using var http=new HttpClient(new FixtureHandler(req=>Task.FromResult(new HttpResponseMessage(HttpStatusCode.Unauthorized){Content=new StringContent("{\"error\":{\"code\":\"InvalidApiKey\"}}",Encoding.UTF8,"application/json")})));string message=Failure(()=>new GuidedAgentClient(http).ReplyAsync(new(){AgentProvider="CUSTOM",LlmEndpoint="http://localhost/v1",Model="fixture"},[new(){Role="user",Content="明天去南京大学"}],default).GetAwaiter().GetResult());Equal(true,message.Contains("InvalidApiKey")&&message.Contains("本轮未写入行程"));});
        test("event extraction retains service code on authorization rejection",()=>{using var http=new HttpClient(new FixtureHandler(req=>Task.FromResult(new HttpResponseMessage(HttpStatusCode.Unauthorized){Content=new StringContent("{\"error\":{\"code\":\"invalid_api_key\"}}")})));string message=Failure(()=>new RepositoryAgentClient(http).ExtractAsync(new(){AgentProvider="CUSTOM",LlmEndpoint="http://localhost/v1",Model="fixture"},"明天去南京大学",default).GetAwaiter().GetResult());Equal(true,message.Contains("invalid_api_key"));});
        test("scoped editor retains service code on authorization rejection",()=>{using var http=new HttpClient(new FixtureHandler(req=>Task.FromResult(new HttpResponseMessage(HttpStatusCode.Unauthorized){Content=new StringContent("{\"error\":{\"code\":\"invalid_api_key\"}}")})));string message=Failure(()=>new LlmClient(http).BuildAsync(new(){AgentProvider="CUSTOM",LlmEndpoint="http://localhost/v1",Model="fixture"},"调整行程",new ScopeContext(),default).GetAwaiter().GetResult());Equal(true,message.Contains("invalid_api_key"));});
        if(OperatingSystem.IsWindows())test("encrypted legacy key is trimmed in actual Bailian conversation request",()=>{using var http=new HttpClient(new FixtureHandler(async req=>{Equal("sk-fixture",req.Headers.Authorization!.Parameter);Equal("https://dashscope.aliyuncs.com/compatible-mode/v1/chat/completions",req.RequestUri!.AbsoluteUri);using var json=System.Text.Json.JsonDocument.Parse(await req.Content!.ReadAsStringAsync());Equal("qwen-plus",json.RootElement.GetProperty("model").GetString());return new(HttpStatusCode.Unauthorized){Content=new StringContent("{\"error\":{\"code\":\"invalid_api_key\"}}")};}));string message=Failure(()=>new GuidedAgentClient(http).ReplyAsync(new(){AgentProvider="BAILIAN",LlmKeyProtected=SettingsStore.Protect(" \r\nsk-fixture\t ")},[new(){Role="user",Content="明天去南京大学"}],default).GetAwaiter().GetResult());Equal(true,message.Contains("invalid_api_key"));});
        test("diagnostic cancellation is preserved",()=>{using var source=new CancellationTokenSource();source.Cancel();using var response=new HttpResponseMessage(HttpStatusCode.Unauthorized){Content=new StringContent("{}")} ;try{ModelHttp.EnsureSuccessAsync(response,new("https://dashscope.aliyuncs.com/v1"),"服务",source.Token).GetAwaiter().GetResult();throw new Exception("expected cancellation");}catch(OperationCanceledException){}});
    }
}
